import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useStore } from 'vuex';
import defaultAvatar from '@/assets/default-avatar.png';
import { API_CONFIG } from '@/config/config';
import { ElMessage, ElNotification } from 'element-plus';
import axios from 'axios';
import CryptoUtils from '@/utils/crypto';
import emojis from '@/utils/emojis';
import GroupInfo from '../components/GroupInfo.vue';
export default {
  components: {
    GroupInfo
  },
  setup() {
    const route = useRoute();
    const router = useRouter();
    const store = useStore();
    const messagesContainer = ref(null);
    const targetGroup = ref({});
    const messages = ref([]);
    const inputMessage = ref('');
    const myAvatar = computed(() => {
      const user = store.state.user;
      return user.photo ? `${API_CONFIG.BASE_URL}${user.photo}` : defaultAvatar;
    });
    const socket = ref(null);
    const isConnected = ref(false);
    const reconnecting = ref(false);
    const reconnectTimer = ref(null);
    const myId = computed(() => store.state.user.id);
    const myUser = computed(() => store.state.user);
    const cryptoUtils = new CryptoUtils();
    const showEmojiPicker = ref(false);
    const messageInput = ref(null);
    const fileInput = ref(null);
    const uploadProgress = ref(0);
    const isUploading = ref(false);

    // 重连相关变量
    const reconnectAttempts = ref(0);
    const maxReconnectAttempts = 5;
    const connectionTimeout = ref(null);

    // 群成员信息
    const groupMembers = ref([]);

    // 加载状态
    const isLoading = ref(true);
    const loadError = ref(null);

    // 系统消息
    const systemMessages = ref([]);

    // 计算属性
    const displayGroupName = computed(() => {
      return targetGroup.value?.group_name || '未知群聊';
    });
    const showGroupInfo = ref(false);
    const getFullUrl = path => {
      if (!path) return defaultAvatar;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const getFileName = url => {
      if (!url) return '文件';
      const parts = url.split('/');
      return parts[parts.length - 1] || '文件';
    };
    const formatTime = time => {
      if (!time) return '';
      const date = new Date(time);
      const now = new Date();
      if (date.toDateString() === now.toDateString()) {
        return date.toTimeString().substring(0, 5);
      }
      const yesterday = new Date();
      yesterday.setDate(now.getDate() - 1);
      if (date.toDateString() === yesterday.toDateString()) {
        return '昨天';
      }
      return `${date.getMonth() + 1}/${date.getDate()}`;
    };
    const getFileIcon = item => {
      if (!item || typeof item !== 'object') return 'fa fa-file-o';
      const fileName = item.original_name || '';
      const url = item.url || '';
      const contentType = item.content_type || '';
      let ext = '';
      if (fileName.includes('.')) {
        ext = fileName.split('.').pop().toLowerCase();
      } else if (url.includes('.')) {
        ext = url.split('.').pop().toLowerCase();
      }
      if (contentType.includes('image')) return 'fa fa-file-image-o';
      if (contentType.includes('video')) return 'fa fa-file-video-o';
      if (contentType.includes('audio')) return 'fa fa-file-audio-o';
      if (contentType.includes('pdf')) return 'fa fa-file-pdf-o';
      if (contentType.includes('word')) return 'fa fa-file-word-o';
      if (contentType.includes('excel') || contentType.includes('spreadsheet')) return 'fa fa-file-excel-o';
      if (contentType.includes('powerpoint') || contentType.includes('presentation')) return 'fa fa-file-powerpoint-o';
      const iconMap = {
        doc: 'fa fa-file-word-o',
        docx: 'fa fa-file-word-o',
        xls: 'fa fa-file-excel-o',
        xlsx: 'fa fa-file-excel-o',
        csv: 'fa fa-file-excel-o',
        ppt: 'fa fa-file-powerpoint-o',
        pptx: 'fa fa-file-powerpoint-o',
        txt: 'fa fa-file-text-o',
        zip: 'fa fa-file-archive-o',
        rar: 'fa fa-file-archive-o',
        '7z': 'fa fa-file-archive-o',
        default: 'fa fa-file-o'
      };
      return iconMap[ext] || iconMap.default;
    };
    const formatFileSize = bytes => {
      if (!bytes) return '0 B';
      const units = ['B', 'KB', 'MB', 'GB'];
      let size = bytes;
      let unitIndex = 0;
      while (size >= 1024 && unitIndex < units.length - 1) {
        size /= 1024;
        unitIndex++;
      }
      return `${size.toFixed(unitIndex === 0 ? 0 : 1)} ${units[unitIndex]}`;
    };
    const formatMessage = text => {
      if (!text) return '';
      return text.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, emoji => `<span class="emoji-inline">${emoji}</span>`);
    };
    const toggleEmojiPicker = () => {
      showEmojiPicker.value = !showEmojiPicker.value;
    };
    const insertEmoji = emoji => {
      if (messageInput.value) {
        const input = messageInput.value;
        const start = input.selectionStart;
        const end = input.selectionEnd;
        inputMessage.value = inputMessage.value.substring(0, start) + emoji + inputMessage.value.substring(end);
        nextTick(() => {
          if (messageInput.value) {
            messageInput.value.focus();
            messageInput.value.setSelectionRange(start + 1, start + 1);
          }
        });
      }
    };

    // 获取成员头像
    const getMemberAvatar = memberId => {
      if (memberId === myId.value) {
        return myAvatar.value;
      }
      const member = groupMembers.value.find(m => m.id === memberId);
      return member?.photo ? getFullUrl(member.photo) : defaultAvatar;
    };

    // 获取前N个成员
    const getFirstMembers = (members, count) => {
      if (!members) return [];
      return members.slice(0, count);
    };

    // 获取头像位置样式
    const getAvatarPosition = index => {
      const positions = [{
        top: '0%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '0%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '33%',
        left: '33%',
        width: '33%',
        height: '33%'
      }];
      return positions[index] || positions[0];
    };

    // 初始化WebSocket连接
    const initWebSocket = () => {
      if (!myId.value || !targetGroup.value.group_id) {
        console.error("无法初始化WebSocket: 缺少用户ID或群ID");
        return;
      }
      const wsUrl = `ws://${API_CONFIG.URL_CHAT}/ws/group/chat/${targetGroup.value.group_id}/${myId.value}`;

      // 关闭现有连接
      if (socket.value) {
        socket.value.onclose = null;
        socket.value.onerror = null;
        socket.value.close();
      }
      socket.value = new WebSocket(wsUrl);
      socket.value.onopen = () => {
        console.log("WebSocket连接成功");
        isConnected.value = true;
        reconnecting.value = false;
        reconnectAttempts.value = 0;
        isLoading.value = false;
        loadError.value = null;
        ElNotification({
          title: '连接成功',
          message: `已加入 ${displayGroupName.value}`,
          type: 'success',
          duration: 3000
        });
        loadHistoryMessages();
        loadSystemMessages();
      };
      socket.value.onmessage = async event => {
        resetConnectionTimeout();
        try {
          const messageData = JSON.parse(event.data);
          let msg;
          if (messageData.encrypt_data && messageData.publick_key) {
            msg = await cryptoUtils.decrypt(messageData.encrypt_data, messageData.publick_key);
          } else {
            msg = messageData;
          }

          // 判断是否是系统消息
          if (msg.message_type === 'system') {
            addSystemMessage(msg);
          } else {
            addMessage({
              id: msg.id,
              text: msg.text,
              media: msg.media || [],
              fromId: msg.from_id,
              fromMe: msg.from_id === myId.value,
              time: msg.time,
              from_username: msg.from_username,
              from_photo: msg.from_photo
            });
          }

          // 更新最近聊天列表
          updateRecentChat();
        } catch (e) {
          console.error('解析消息失败', e);
          ElMessage.error('接收消息失败');
        }
      };
      socket.value.onclose = event => {
        console.log("WebSocket连接关闭:", event.code, event.reason);
        isConnected.value = false;
        if (!reconnecting.value && !loadError.value) {
          ElNotification({
            title: '连接断开',
            message: '群聊连接已断开，正在尝试重连...',
            type: 'warning',
            duration: 0
          });
          startReconnect();
        }
      };
      socket.value.onerror = errorEvent => {
        console.error('WebSocket错误', errorEvent);
        isLoading.value = false;
        loadError.value = 'WebSocket连接错误，请稍后重试';
      };

      // 设置连接超时
      resetConnectionTimeout();
    };

    // 重置连接超时计时器
    const resetConnectionTimeout = () => {
      clearTimeout(connectionTimeout.value);
      connectionTimeout.value = setTimeout(() => {
        if (socket.value && socket.value.readyState !== WebSocket.OPEN) {
          console.log('WebSocket连接超时，尝试重连');
          socket.value.close();
          startReconnect();
        }
      }, 10000);
    };

    // 加载历史消息
    const loadHistoryMessages = async () => {
      if (myId.value && targetGroup.value.group_id) {
        try {
          const res = await axios.get(`${API_CONFIG.BASE_URL}/ws/group/chat/history/${myId.value}/${targetGroup.value.group_id}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (res.data && res.data.length) {
            const formattedMessages = res.data.map(msg => ({
              id: msg.id,
              text: msg.text,
              media: msg.media || [],
              fromId: msg.from_id,
              fromMe: msg.from_id === myId.value,
              from_username: msg.from_username,
              from_photo: msg.from_photo,
              time: msg.time
            }));
            messages.value = formattedMessages;
            nextTick(() => {
              if (messagesContainer.value) {
                messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
              }
            });
          }
        } catch (err) {
          console.error('加载历史消息失败', err);
          ElMessage.warning('历史消息加载失败');
        }
      }
    };

    // 加载系统消息
    const loadSystemMessages = async () => {
      if (!targetGroup.value?.group_id) return;
      try {
        const res = await axios.get(`${API_CONFIG.BASE_URL}/group/system-message`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (res.data && Array.isArray(res.data)) {
          systemMessages.value = res.data.filter(msg => msg.message_type === 'system').sort((a, b) => new Date(a.time || a.timestamp) - new Date(b.time || b.timestamp));
        }
      } catch (error) {
        console.error('加载系统消息失败:', error);
      }
    };

    // 重连逻辑
    const startReconnect = () => {
      if (reconnecting.value || !targetGroup.value.group_id) return;
      reconnecting.value = true;
      reconnectAttempts.value++;
      const delay = Math.min(3000 * Math.pow(2, reconnectAttempts.value - 1), 30000);
      if (reconnectAttempts.value === 1 || reconnectAttempts.value >= 3) {
        ElNotification({
          title: '连接断开',
          message: '群聊连接已断开，正在尝试重连...',
          type: 'warning',
          duration: 0
        });
      }
      reconnectTimer.value = setTimeout(() => {
        if (reconnectAttempts.value >= maxReconnectAttempts) {
          ElNotification({
            title: '连接失败',
            message: '无法连接到服务器，请检查网络连接',
            type: 'error',
            duration: 0
          });
          reconnecting.value = false;
          return;
        }
        initWebSocket();
        reconnecting.value = false;
      }, delay);
    };

    // 停止重连
    const stopReconnect = () => {
      if (reconnectTimer.value) {
        clearTimeout(reconnectTimer.value);
        reconnectTimer.value = null;
        reconnecting.value = false;
      }
    };

    // 添加消息
    const addMessage = msg => {
      const exists = messages.value.some(m => m.id === msg.id);
      if (!exists) {
        messages.value.push(msg);
        nextTick(() => {
          if (messagesContainer.value) {
            messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
          }
        });
      }
    };

    // 添加系统消息
    const addSystemMessage = msg => {
      const exists = systemMessages.value.some(m => m.id === msg.id);
      if (!exists) {
        systemMessages.value.push(msg);
        nextTick(() => {
          if (messagesContainer.value) {
            messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
          }
        });
      }
    };

    // 更新最近聊天
    const updateRecentChat = () => {
      store.commit('chat/ADD_RECENT_CHAT', {
        id: targetGroup.value.id,
        username: displayGroupName.value,
        avatar_members: targetGroup.value.avatar_members,
        isGroup: true,
        lastMessage: messages.value[messages.value.length - 1]?.text || '',
        lastMessageTime: new Date().toISOString()
      });
      store.dispatch('chat/saveRecentChat');
    };

    // 处理文件上传
    const handleFileUpload = async event => {
      const file = event.target.files[0];
      if (!file) return;
      try {
        isUploading.value = true;
        uploadProgress.value = 0;
        const formData = new FormData();
        formData.append('file', file);
        const res = await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/upload/media`, formData, {
          headers: {
            'Content-Type': 'multipart/form-data',
            'Authorization': `Bearer ${store.state.token}`
          },
          onUploadProgress: progressEvent => {
            uploadProgress.value = Math.round(progressEvent.loaded * 100 / progressEvent.total);
          }
        });
        if (res.data.success) {
          const mediaType = res.data.type;
          const mediaUrl = res.data.url;
          const original_name = res.data.original_name;
          const size = res.data.size;
          sendMediaMessage(mediaType, mediaUrl, original_name, size);
          ElMessage.success(`${mediaType === 'image' ? '图片' : mediaType === 'video' ? '视频' : '文件'}上传成功`);
        } else {
          ElMessage.error('上传失败：' + res.data.message);
        }
      } catch (error) {
        console.error('文件上传错误', error);
        ElMessage.error('上传失败，请重试');
      } finally {
        isUploading.value = false;
        uploadProgress.value = 0;
        if (fileInput.value) {
          fileInput.value.value = '';
        }
      }
    };

    // 发送媒体消息
    const sendMediaMessage = (type, url, original_name, size) => {
      if (!isConnected.value) {
        ElMessage.warning('当前连接已断开，无法发送消息');
        return;
      }
      const msg = {
        id: Date.now(),
        text: '',
        media: [{
          type,
          url,
          original_name,
          size
        }],
        fromMe: true,
        time: new Date().toISOString()
      };
      addMessage(msg);
      try {
        socket.value.send(JSON.stringify({
          id: msg.id,
          text: '',
          media: msg.media,
          time: msg.time,
          from_id: myId.value,
          group_id: targetGroup.value.id,
          from_username: myUser.value.username,
          from_photo: myUser.value.photo
        }));
      } catch (error) {
        console.error('发送媒体消息失败', error);
        ElMessage.error('消息发送失败，请稍后再试');
      }
      updateRecentChat();
    };

    // 发送文本消息
    const sendMessage = () => {
      const content = inputMessage.value.trim();
      if (!content) {
        ElMessage.warning('消息内容不能为空，请输入后再发送～');
        return;
      }
      if (!isConnected.value) {
        ElMessage.warning('当前连接已断开，无法发送消息');
        return;
      }
      const msg = {
        id: Date.now(),
        text: inputMessage.value.trim(),
        fromMe: true,
        time: new Date().toISOString()
      };
      addMessage(msg);
      inputMessage.value = '';
      try {
        socket.value.send(JSON.stringify({
          id: msg.id,
          text: msg.text,
          time: msg.time,
          from_id: myId.value,
          group_id: targetGroup.value.group_id,
          from_username: myUser.value.username,
          from_photo: myUser.value.photo
        }));
      } catch (error) {
        console.error('发送消息失败', error);
        ElMessage.error('消息发送失败，请稍后再试');
      }
      updateRecentChat();
    };

    // 返回
    const goBack = () => {
      router.back();
      stopReconnect();
      if (socket.value) {
        socket.value.close();
      }
    };

    // 获取发送者头像
    const getSenderAvatar = msg => {
      if (msg.fromMe) return myAvatar.value;
      return msg.from_photo ? getFullUrl(msg.from_photo) : defaultAvatar;
    };

    // 查找发送者名称
    const findSenderName = msg => {
      if (msg.fromMe) return '我';
      return msg.from_username || `用户${msg.fromId}`;
    };
    const groupAvatarUrls = computed(() => {
      if (!targetGroup.value) return [defaultAvatar];

      // 优先使用 avatar_members 或 avatarMembers
      const avatarMembers = targetGroup.value.avatar_members || targetGroup.value.avatarMembers || [];

      // 如果有头像成员列表，直接使用
      if (avatarMembers.length > 0) {
        return avatarMembers.slice(0, 9).map(url => getFullUrl(url)).filter(Boolean);
      }

      // 如果没有头像成员列表，使用成员ID获取头像
      const members = targetGroup.value.members || targetGroup.value.group_members || [];
      return getFirstMembers(members, 9).map(memberId => getMemberAvatar(memberId));
    });

    // 获取群信息
    const fetchGroupInfo = async groupId => {
      isLoading.value = true;
      loadError.value = null;
      try {
        const res = await axios.get(`${API_CONFIG.BASE_URL}/group/${groupId}`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (res.data && res.data.group_id) {
          messages.value = [];
          stopReconnect();
          targetGroup.value = res.data;
          groupMembers.value = res.data.group_members || [];

          // 获取群头像成员
          const avatarMembers = await store.dispatch('chat/fetchGroupAvatar', groupId);
          targetGroup.value.avatarMembers = avatarMembers || [];
          if (myId.value) {
            initWebSocket();
          } else {
            console.error("用户未登录，无法初始化WebSocket连接");
            loadError.value = '用户未登录，请重新登录';
          }
        } else {
          throw new Error('群聊信息为空');
        }
      } catch (err) {
        console.error('获取群聊信息失败', err);
        loadError.value = '获取群聊信息失败，请稍后重试';
        isLoading.value = false;
      }
    };

    // 点击外部关闭表情选择器
    const handleOutsideClick = event => {
      if (showEmojiPicker.value) {
        const emojiPicker = document.querySelector('.emoji-picker');
        const emojiBtn = document.querySelector('.emoji-btn');
        if (emojiPicker && !emojiPicker.contains(event.target) && emojiBtn && !emojiBtn.contains(event.target)) {
          showEmojiPicker.value = false;
        }
      }
    };

    // 监听路由变化
    watch(() => route.params.id, newId => {
      if (newId) {
        fetchGroupInfo(newId);
      }
    });

    // 组件挂载
    onMounted(() => {
      if (route.params.id) {
        fetchGroupInfo(route.params.id);
      } else {
        loadError.value = '未指定群聊ID';
        isLoading.value = false;
      }
      document.addEventListener('click', handleOutsideClick);
    });

    // 组件卸载
    onUnmounted(() => {
      stopReconnect();
      if (socket.value) {
        socket.value.close();
      }
      document.removeEventListener('click', handleOutsideClick);
    });
    return {
      targetGroup,
      messages,
      systemMessages,
      inputMessage,
      myAvatar,
      getFullUrl,
      getFileName,
      formatTime,
      formatMessage,
      sendMessage,
      goBack,
      messagesContainer,
      isConnected,
      showEmojiPicker,
      getMemberAvatar,
      getFirstMembers,
      groupAvatarUrls,
      messageInput,
      fileInput,
      uploadProgress,
      isUploading,
      toggleEmojiPicker,
      handleFileUpload,
      insertEmoji,
      getFileIcon,
      formatFileSize,
      emojis,
      groupMembers,
      getSenderAvatar,
      findSenderName,
      isLoading,
      loadError,
      displayGroupName,
      getAvatarPosition,
      showGroupInfo
    };
  }
};
